WITH filtered AS (SELECT *, DAYOFWEEK(txn_time) AS txn_time_dayofweek, DATEDIFF(CURRENT_DATE(), txn_time) / 365.25 AS years_since_txn_time, COALESCE(merchant, 'UNKNOWN') AS merchant_filled FROM transactions WHERE merchant IS NOT NULL AND merchant IN ('Starbucks', 'Grab', 'Lazada')), deduped AS (SELECT * FROM filtered QUALIFY ROW_NUMBER() OVER (PARTITION BY txn_type, account_id ORDER BY years_since_txn_time NULLS FIRST, id) = 1), enriched AS (SELECT a.id, a.account_id, a.txn_type, a.amount, a.merchant, a.is_flagged, a.txn_time_dayofweek, a.years_since_txn_time, p.opened_date, p.status FROM deduped a LEFT JOIN accounts p ON a.account_id = p.id), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY txn_time_dayofweek, id) AS latest_rank FROM enriched) t WHERE latest_rank = 1) SELECT DATE_TRUNC('YEAR', opened_date) AS year_start, APPROX_PERCENTILE(amount, 0.5) AS amount_p50, ROUND(SUM(txn_time_dayofweek) / NULLIF(COUNT(CASE WHEN status = 'CLOSED' THEN 1 END), 0), 2) AS txn_time_dayofweek_per_closed, COUNT(CASE WHEN merchant = 'Grab' THEN 1 END) AS grab_count FROM latest GROUP BY 1 ORDER BY year_start NULLS FIRST;
